	SUBROUTINE MOVDAT(NM)
	INTEGER*2 I,J,NM
C
      INTEGER*2 IX
      COMMON/ABLE/IX(5762)
C
      INTEGER*2 MHV,IDM
      REAL*4 XD
      COMMON/BAKER/MHV(360,2),IDM(3,2),XD
C
	INTEGER*2 LX
	COMMON/CHARLY/LX(2882)
C
      DO 10 I=1,2880			!SAVE 1-MIN H AND D FROM
      LX(I)=IX(I)			!CURRENT DAT TO LX
   10 CONTINUE
      LX(2881)=IX(5761)
      LX(2882)=IX(5762)
      DO 30 J=1,2
	DO 20 I=1,NM
	K=NM+I
	KK=2*NM+I
	MHV(I,J)=MHV(K,J)
   20 MHV(K,J)=MHV(KK,J)
      IDM(1,J)=IDM(2,J)
      IDM(2,J)=IDM(3,J)
   30 CONTINUE
      RETURN
      END
